(()=>{const scenes=["<div class=\"stories\"><div class=\"story\"><div class=\"circle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 5v14M5 12h14\"/></svg></div><p>Tạo tin</p></div><div class=\"story\"><img class=\"avatar\" style=\"width:33px;height:33px\" src=\"/people/1.jpg\"><p>Minh Anh</p></div></div><div class=\"composer\"><img class=\"avatar\" src=\"/people/1.jpg\">Bạn đang nghĩ gì?</div><div class=\"author\"><img class=\"avatar\" src=\"/people/1.jpg\"><span><b>Minh Anh · 27</b><br><small>Hồ sơ minh họa</small></span></div><div class=\"caption\">Tập luyện mỗi ngày</div><img class=\"postphoto\" src=\"/people/1.jpg\"><div class=\"actions\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8\"/></svg><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21 11.5a8.4 8.4 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.4 8.4 0 0 1-3.8-.9L3 21l1.9-5.7a8.4 8.4 0 0 1-.9-3.8 8.5 8.5 0 0 1 4.7-7.6 8.4 8.4 0 0 1 3.8-.9h.5a8.5 8.5 0 0 1 8 8v.5Z\"/></svg><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M18 8a3 3 0 1 0 0-6 3 3 0 0 0 0 6ZM6 15a3 3 0 1 0 0-6 3 3 0 0 0 0 6ZM18 22a3 3 0 1 0 0-6 3 3 0 0 0 0 6ZM8.6 10.5l6.8-4M8.6 13.5l6.8 4\"/></svg></div>", "<div class=\"segments\"><b>Dành cho bạn</b><span>Quanh đây</span><span>Đang theo dõi</span></div><div class=\"searchbox\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0\"/></svg>Tên hoặc @username</div><div class=\"filters\"><span>Tuổi</span><span>Cân nặng</span><span>Chiều cao</span><span>Giới tính</span><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M4 6h16M4 12h16M4 18h16M9 3v6M16 9v6M9 15v6\"/></svg></div><div class=\"peoplegrid\"><div class=\"person\"><img src=\"/welcome-profile.png?v=20261029-demo-photos-1\"><b>Minh Anh, 27</b></div><div class=\"person\"><img src=\"/welcome-profile-1.png?v=20261029-demo-photos-1\"><b>Gia Huy, 28</b></div><div class=\"person\"><img src=\"/welcome-profile-2.png?v=20261029-demo-photos-1\"><b>Hoàng Nam, 30</b></div><div class=\"person\"><img src=\"/welcome-profile-3.png?v=20261029-demo-photos-1\"><b>Quang Minh, 26</b></div></div>", "<div class=\"reel\"><img src=\"/people/1.jpg\"><div class=\"reeltop\"><b>Đề xuất</b><span>Đang theo dõi</span></div><div class=\"reelcontrols\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 5v14M5 12h14\"/></svg><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8\"/></svg><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21 11.5a8.4 8.4 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.4 8.4 0 0 1-3.8-.9L3 21l1.9-5.7a8.4 8.4 0 0 1-.9-3.8 8.5 8.5 0 0 1 4.7-7.6 8.4 8.4 0 0 1 3.8-.9h.5a8.5 8.5 0 0 1 8 8v.5Z\"/></svg><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M18 8a3 3 0 1 0 0-6 3 3 0 0 0 0 6ZM6 15a3 3 0 1 0 0-6 3 3 0 0 0 0 6ZM18 22a3 3 0 1 0 0-6 3 3 0 0 0 0 6ZM8.6 10.5l6.8-4M8.6 13.5l6.8 4\"/></svg></div><div class=\"reelcaption\"><b>@minhanh_demo</b><br>Video minh họa</div></div>", "<div class=\"reel\"><img src=\"/people/1.jpg\"><div style=\"position:absolute;top:8px;left:8px;color:white;font-size:10px\"><b style=\"background:#ff4f9a;border-radius:5px;padding:4px 8px\">LIVE</b> · Minh họa</div><div class=\"reelcaption\"><b>Minh Anh đang trực tiếp</b><p>Chào mừng đến với Kinnect</p></div></div>"];const names=['Bảng tin','Khám phá','Video','Live'];let current=0;function show(i){document.querySelector('#feature').innerHTML=scenes[i];document.querySelector('#tabtitle').textContent=names[i]+' · Hồ sơ mẫu';document.querySelectorAll('[data-nav]').forEach((el,n)=>el.classList.toggle('selected',n===[0,1,3,4][i]));}show(0);document.dispatchEvent(new Event("kinnect:demo-ready"));setInterval(()=>{const f=document.querySelector('#feature');f.style.opacity=0;setTimeout(()=>{current=(current+1)%4;show(current);f.style.opacity=1},320)},1500);;document.querySelectorAll("[data-nav]").forEach((el,i)=>el.addEventListener("click",()=>{if(i===2)top.location.href="https://app.kinnect.io.vn/download/android";else{current=i<2?i:i-1;show(current)}}));;})();
